#include <algorithm>
#include <map>
#include <set>
#include <string>
#include <vector>

struct Mod { std::string id; std::vector<std::string> requires_; std::vector<std::string> after; };
struct LoadResult { std::vector<std::string> order; std::vector<std::string> disabled; };

LoadResult loadOrder(const std::vector<Mod>& mods)
{
    std::map<std::string, const Mod*> byId;
    for (const Mod& m : mods) byId[m.id] = &m;

    // 1. Disable mods with missing requirements, repeatedly.
    std::set<std::string> enabled;
    for (const Mod& m : mods) enabled.insert(m.id);
    bool changed{ true };
    while (changed)
    {
        changed = false;
        for (auto it{ enabled.begin() }; it != enabled.end();)
        {
            bool ok{ true };
            for (const std::string& r : byId[*it]->requires_)
                if (!enabled.count(r)) ok = false;
            if (!ok) { it = enabled.erase(it); changed = true; }
            else ++it;
        }
    }

    // 2. Edges among enabled mods: dependency -> dependant.
    std::map<std::string, std::set<std::string>> dependants;
    std::map<std::string, int> waiting;
    for (const std::string& id : enabled) waiting[id] = 0;
    for (const std::string& id : enabled)
    {
        std::set<std::string> firsts;
        for (const std::string& r : byId[id]->requires_) firsts.insert(r);
        for (const std::string& a : byId[id]->after)
            if (enabled.count(a)) firsts.insert(a);
        for (const std::string& f : firsts)
            if (dependants[f].insert(id).second) ++waiting[id];
    }

    // 3. Kahn's algorithm, smallest ready id first.
    std::set<std::string> ready;
    for (const auto& [id, count] : waiting)
        if (count == 0) ready.insert(id);
    LoadResult result;
    while (!ready.empty())
    {
        const std::string id{ *ready.begin() };
        ready.erase(ready.begin());
        result.order.push_back(id);
        for (const std::string& d : dependants[id])
            if (--waiting[d] == 0) ready.insert(d);
    }

    // 4. Everything not ordered is disabled.
    std::set<std::string> ordered(result.order.begin(), result.order.end());
    for (const Mod& m : mods)
        if (!ordered.count(m.id)) result.disabled.push_back(m.id);
    std::sort(result.disabled.begin(), result.disabled.end());
    return result;
}

unitTests:
TEST("independent mods load alphabetically")
{
    const auto r{ loadOrder({ { "zeta", {}, {} }, { "alpha", {}, {} }, { "mid", {}, {} } }) };
    CHECK_EQ(r.order.size(), std::size_t{ 3 });
    CHECK_EQ(r.order[0], std::string("alpha")); CHECK_EQ(r.order[1], std::string("mid")); CHECK_EQ(r.order[2], std::string("zeta"));
    CHECK(r.disabled.empty());
}
TEST("requirements load first")
{
    const auto r{ loadOrder({ { "aaa", { "core" }, {} }, { "core", {}, {} } }) };
    CHECK_EQ(r.order[0], std::string("core")); CHECK_EQ(r.order[1], std::string("aaa"));
}
TEST("after hints are respected only when present")
{
    const auto r{ loadOrder({ { "a", {}, { "b", "ghost" } }, { "b", {}, {} } }) };
    CHECK_EQ(r.order.size(), std::size_t{ 2 });
    CHECK_EQ(r.order[0], std::string("b")); CHECK_EQ(r.order[1], std::string("a"));
}
TEST("missing requirements disable a chain")
{
    const auto r{ loadOrder({ { "lantern", { "core-items" }, {} }, { "lantern-plus", { "lantern" }, {} }, { "other", {}, {} } }) };
    CHECK_EQ(r.order.size(), std::size_t{ 1 }); CHECK_EQ(r.order[0], std::string("other"));
    CHECK_EQ(r.disabled.size(), std::size_t{ 2 }); CHECK_EQ(r.disabled[0], std::string("lantern")); CHECK_EQ(r.disabled[1], std::string("lantern-plus"));
}
TEST("a cycle disables its members and their dependants")
{
    const auto r{ loadOrder({ { "x", { "y" }, {} }, { "y", {}, { "x" } }, { "w", { "x" }, {} }, { "free", {}, {} } }) };
    CHECK_EQ(r.order.size(), std::size_t{ 1 }); CHECK_EQ(r.order[0], std::string("free"));
    CHECK_EQ(r.disabled.size(), std::size_t{ 3 }); CHECK_EQ(r.disabled[0], std::string("w"));
}
TEST("ties broken at every step")
{
    const auto r{ loadOrder({ { "core", {}, {} }, { "b", { "core" }, {} }, { "a", { "core" }, {} }, { "0first", {}, {} } }) };
    CHECK_EQ(r.order[0], std::string("0first")); CHECK_EQ(r.order[1], std::string("core")); CHECK_EQ(r.order[2], std::string("a")); CHECK_EQ(r.order[3], std::string("b"));
}

